import util, { MIMEType, MIMEParams } from "node:util";
import { createRequire } from "node:module";

const show = (label, ...values) => console.log(label + " " + JSON.stringify(values));
const failure = (fn) => {
  try { fn(); return ["did-not-throw"]; }
  catch (error) { return [error.name, error.code ?? null, error.message]; }
};

export function report() {
  const required = createRequire(import.meta.url)("util");
  show("exports", util.MIMEType === MIMEType, util.MIMEParams === MIMEParams,
    required.MIMEType === MIMEType, required.MIMEParams === MIMEParams);
  const samples = [
    "text/plain", "APPLICATION/JSON", "\r\n\t TeXt/HTML \t\r\n",
    "application/vnd.example+json; CHARSET=UTF-8; boundary=abc",
    "text/plain;foo=first;FOO=second;foo=third",
    'text/plain;a="";b="hello world";c="a;=b"',
    'text/plain;a="quote\\\" and slash\\\\";b=end',
    'text/plain;a="unterminated', 'text/plain;a="trailing\\',
    'text/plain;a="value"ignored;b=last',
    "text/plain;bad;empty=;=value;bad name=x;good=yes;missing",
    "text/plain;a=   ;b= value \t\r\n;c=keep",
    "text/plain;x=\u0000;y=\u0100;z=é;tab=\tvalue;last=ok",
    'text/plain;x="\r";y="\n";z="\u007f";next=valid',
    'text/plain;x="\t é";X=ignored;quote="a\\b"',
    "text/plain;;; \t;foo=bar;;",
    "text/plain;__proto__=safe;constructor=also-safe",
    "text/plain;name=value=with=equals",
    "text/plain;name=\"quoted\";empty=\"\"\r\n",
    "*/*", "application/x-a!#$%&'*+-.^_`|~0123456789",
  ];
  for (const input of samples) {
    const mime = new MIMEType(input);
    show("parse", input, mime.type, mime.subtype, mime.essence,
      [...mime.params], String(mime), mime.toJSON(), JSON.stringify(mime));
  }
  const mime = new MIMEType({ toString: () => "TeXt/PLAIN;a=1;b=2" });
  const params = mime.params;
  show("shape", Object.keys(mime), Object.keys(params), params instanceof MIMEParams,
    mime.params === params, mime.toJSON === mime.toString,
    params.toJSON === params.toString, params[Symbol.iterator] === params.entries);
  for (const key of ["type", "subtype", "essence", "params"]) {
    const descriptor = Object.getOwnPropertyDescriptor(MIMEType.prototype, key);
    show("descriptor", key, typeof descriptor.get, typeof descriptor.set,
      descriptor.enumerable, descriptor.configurable);
  }
  mime.type = "APPLICATION";
  mime.subtype = { toString: () => "JSON" };
  show("mutate-type", mime.essence, String(mime), mime.params === params);
  show("get", params.get("a"), params.get("A"), params.get("missing"),
    params.has("a"), params.has("A"), params.has("missing"));
  show("set-return", params.set("a", "updated"));
  params.set("A", "case-sensitive");
  params.set("empty", "");
  params.set("quoted", 'space;equals=quote"slash\\');
  params.set("latin1", "\téÿ");
  params.set({ toString: () => "coerced" }, { toString: () => "42" });
  params.set(7, false);
  show("parameters", [...params.entries()], [...params.keys()], [...params.values()],
    String(params), params.toJSON(), JSON.stringify(params), String(mime));
  const key = { toString() { throw new Error("readers must not coerce"); } };
  show("no-read-coercion", params.get(key), params.has(key), params.delete(key));
  show("delete-return", params.delete("b"), params.delete("missing"));
  params.set("b", "reinserted");
  show("delete-order", [...params]);
  const empty = new MIMEParams("ignored constructor input");
  show("empty", [...empty], empty.get("missing"), String(empty), JSON.stringify(empty));

  // Iterators are lazy and remain live as the underlying parameter map changes.
  const live = new MIMEType("text/plain;first=1;second=2").params;
  const iterator = live.entries();
  live.set("third", "3");
  show("iterator-first", iterator.next());
  live.delete("second");
  live.set("third", "updated");
  live.set("fourth", "4");
  show("iterator-rest", iterator.next(), iterator.next(), iterator.next());
  const keys = live.keys();
  const values = live.values();
  live.set("fifth", "5");
  show("lazy-iterators", [...keys], [...values]);
  const close = live.entries();
  show("iterator-close", close.next(), close.return("closed"), close.next());

  // MIMEType serialization uses the original parameter serializer, rather than overrides.
  params.toString = () => "overridden";
  params.entries = () => { throw new Error("overridden"); };
  show("serializer", String(params), String(mime), JSON.stringify(mime));
  const original = MIMEParams.prototype.toString;
  MIMEParams.prototype.toString = () => "prototype override";
  try { show("prototype-serializer", String(new MIMEType("image/png;a=b"))); }
  finally { MIMEParams.prototype.toString = original; }
  mime.toString = () => "user override";
  show("json-alias", String(mime), mime.toJSON(), JSON.stringify(mime));

  // Pin every ASCII character's token and quoted-value acceptance and round trip.
  for (let code = 0; code < 128; code++) {
    const char = String.fromCharCode(code);
    const p = new MIMEParams();
    let token, value;
    try { p.set("x" + char, "ok"); token = String(p); }
    catch (e) { token = e.code; }
    try { p.set("value", char); value = new MIMEType("text/plain;" + p).params.get("value"); }
    catch (e) { value = e.code; }
    show("ascii", code, token, value);
  }
}

export function reportErrors() {
  const badInputs = ["", "text", "text/", "/plain", "text /plain", "text/ plain",
    "text/pl ain", "text/plain/other", "text/\u0100", "\u00a0text/plain",
    "text/pla💩in", null, undefined, false, 42];
  for (const input of badInputs) console.error(JSON.stringify(["constructor", input,
    failure(() => new MIMEType(input))]));
  const mime = new MIMEType("text/plain;a=unchanged");
  for (const field of ["type", "subtype"]) {
    for (const value of ["", "a b", "a/b", "a;", "é", "\n", "💩", "valid\u007f"]) {
      console.error(JSON.stringify(["setter", field, value,
        failure(() => { mime[field] = value; }), String(mime)]));
    }
  }
  for (const [name, value] of [["", "ok"], ["a b", "ok"], ["a=", "ok"],
    ["a", "\n"], ["a", "\r"], ["a", "\u0000"], ["a", "\u007f"], ["a", "Ā"], ["a", "💩"]]) {
    console.error(JSON.stringify(["set", name, value,
      failure(() => mime.params.set(name, value)), String(mime)]));
  }
  // Engine-specific wording for ordinary JS errors is outside the MIME error contract.
  const errorName = (fn) => { try { fn(); return "did-not-throw"; } catch (e) { return e.name; } };
  const typeGetter = Object.getOwnPropertyDescriptor(MIMEType.prototype, "type").get;
  const essenceGetter = Object.getOwnPropertyDescriptor(MIMEType.prototype, "essence").get;
  console.error(JSON.stringify(["brand", errorName(() => typeGetter.call({})),
    errorName(() => essenceGetter.call({})), errorName(() => MIMEType.prototype.toString.call({})),
    errorName(() => MIMEParams.prototype.get.call({}, "x")),
    errorName(() => MIMEParams.prototype.entries.call({}).next())]));
  console.error(JSON.stringify(["readonly", errorName(() => { mime.essence = "x/y"; }),
    errorName(() => { mime.params = new MIMEParams(); }), String(mime)]));
  console.error(JSON.stringify(["symbol", errorName(() => new MIMEType(Symbol("x"))),
    errorName(() => { mime.type = Symbol("x"); }),
    errorName(() => mime.params.set(Symbol("x"), "ok")),
    errorName(() => mime.params.set("a", Symbol("x")))]));
  process.exitCode = 3;
}
